            linear.select(this._titleDiv)
                .style('height', this._prevHeight)
                .transition('adjust')
                .duration(400)
                .style('height', height)
                .on('end', () => linear.select(this._titleDiv).style('height', null));
            linear.select(this._legendDiv)
                .style('opacity', 0)
                .transition()
                .duration(400)
                .ease(linear.polyInOut)
                .style('opacity', 1);
